#!/usr/bin/env bash
# Generated by: GPT-6 (Codex)
# 先检查入口和语法，再启动 Zsh/Vim 验证实际加载的功能。
set -euo pipefail
source "$(dirname -- "${BASH_SOURCE[0]}")/lib.sh"
if [[ $# != 0 ]]; then
  die 'Usage: scripts/verify.sh'
fi
export PATH="$DF_HOME/.local/bin:$PATH"
check_dependencies
# 防止旧配置也能正常启动，导致误判为迁移成功。
for relative in .zshrc .zshenv .vimrc .vim .tmux.conf .local/bin/fzf; do
  case $relative in
    .zshrc|.zshenv)
      source="$DOTFILES_ROOT/config/zsh/$relative"
      ;;
    .vimrc|.vim)
      source="$DOTFILES_ROOT/config/vim/$relative"
      ;;
    .tmux.conf)
      source="$DOTFILES_ROOT/config/tmux/$relative"
      ;;
    .local/bin/fzf)
      source="$DOTFILES_ROOT/config/vim/.vim/bundle/fzf/bin/fzf"
      ;;
  esac
  if [[ ! -L $DF_HOME/$relative || $(readlink -f -- "$DF_HOME/$relative") != $(realpath -- "$source") ]]; then
    die "Wrong link: $relative"
  fi
done
shell_files=(
  "$DOTFILES_ROOT"/install.sh
  "$DOTFILES_ROOT"/scripts/*.sh
  "$DOTFILES_ROOT"/config/{zsh,vim,tmux}/install.sh
)
for file in "${shell_files[@]}"; do
  bash -n "$file"
done

zsh_files=(
  "$DOTFILES_ROOT"/config/zsh/{.zshrc,.zshenv,*.zsh}
  "$DOTFILES_ROOT"/config/tools/*.zsh
  "$DOTFILES_ROOT"/config/fzf/*.zsh
)
for file in "${zsh_files[@]}"; do
  zsh -n "$file"
done

# script 提供伪终端，避免无终端的 zsh -ic 无法正确恢复 ZLE 选项。
env HOME="$DF_HOME" ZDOTDIR="$DF_HOME" XDG_CACHE_HOME="$DF_HOME/.cache" \
  DOTFILES_EXPECTED_ROOT="$DOTFILES_ROOT" TERM=xterm-256color \
  script -qec 'zsh -d -i "$DOTFILES_EXPECTED_ROOT/scripts/check.zsh"' /dev/null </dev/null
# Vim 不读写 viminfo；失败时保留日志，以便看到具体断言。
vim_log=$(mktemp)
if ! env HOME="$DF_HOME" vim -i NONE -n -es -u "$DF_HOME/.vimrc" -V1"$vim_log" -S "$DOTFILES_ROOT/scripts/check.vim"; then
  cat "$vim_log" >&2
  die "Vim smoke test failed; log: $vim_log"
fi
rm -f -- "$vim_log"
# 无界面的 fzf 过滤检查；实际按键操作另见验证文档。
printf 'needle\nother\n' | fzf --filter=needle | rg -x needle >/dev/null
printf 'PASS: links, syntax, Vim commands/maps and fzf (%s)\n' "$(fzf --version)"
echo 'For isolated tmux, install/rollback and file-search tests: scripts/test.sh'
